  app.get('/api/v1/admin/users', async (request, reply) => { const req=request as AuthenticatedRequest; if(!requireAuth(req,reply))return; if(!hasRole(req,['SYSTEM_ADMINISTRATOR']))return reply.code(403).send({error:'forbidden'}); const query=z.object({search:z.string().max(100).optional(),status:z.enum(['ACTIVE','SUSPENDED','DISABLED']).optional(),roleId:z.string().uuid().optional(),page:z.coerce.number().int().min(1).default(1),pageSize:z.coerce.number().int().min(1).max(100).default(50)}).parse(request.query); const values:any[]=[]; const where:string[]=[]; if(query.search){values.push(`%${query.search}%`);where.push(`(u.username ILIKE $${values.length} OR u.display_name ILIKE $${values.length} OR u.email ILIKE $${values.length})`)} if(query.status){values.push(query.status);where.push(`u.status=$${values.length}`)} if(query.roleId){values.push(query.roleId);where.push(`EXISTS (SELECT 1 FROM user_roles filter_ur WHERE filter_ur.user_id=u.id AND filter_ur.role_id=$${values.length})`)} const offset=(query.page-1)*query.pageSize; values.push(query.pageSize,offset); const result=await pool.query(`SELECT u.id,u.username,u.email,u.display_name,u.status,u.created_at,COALESCE(array_agg(r.name) FILTER (WHERE r.name IS NOT NULL),'{}') AS roles,CASE WHEN bool_or(r.name IN ('SYSTEM_ADMINISTRATOR','NATIONAL_ADMINISTRATOR')) THEN 'NATIONAL' WHEN bool_or(r.name IN ('ASSOCIATION_ADMINISTRATOR','ASSOCIATION_REPRESENTATIVE')) THEN 'ASSOCIATION' WHEN bool_or(r.name='DAIRA_OFFICER') THEN 'DAIRA' WHEN bool_or(r.name='MEMBER_INSTITUTION_USER') THEN 'INSTITUTION' ELSE NULL END AS scope_type,CASE WHEN bool_or(r.name IN ('SYSTEM_ADMINISTRATOR','NATIONAL_ADMINISTRATOR')) THEN NULL WHEN bool_or(r.name IN ('ASSOCIATION_ADMINISTRATOR','ASSOCIATION_REPRESENTATIVE')) THEN u.organization_id::text WHEN bool_or(r.name='DAIRA_OFFICER') THEN u.daira_id::text WHEN bool_or(r.name='MEMBER_INSTITUTION_USER') THEN u.institution_id::text ELSE NULL END AS scope_id,CASE WHEN bool_or(r.name IN ('SYSTEM_ADMINISTRATOR','NATIONAL_ADMINISTRATOR')) THEN 'النطاق الوطني' WHEN bool_or(r.name IN ('ASSOCIATION_ADMINISTRATOR','ASSOCIATION_REPRESENTATIVE')) THEN o.name WHEN bool_or(r.name='DAIRA_OFFICER') THEN d.name WHEN bool_or(r.name='MEMBER_INSTITUTION_USER') THEN i.name ELSE NULL END AS scope_name FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id LEFT JOIN organizations o ON o.id=u.organization_id LEFT JOIN dairas d ON d.id=u.daira_id LEFT JOIN educational_institutions i ON i.id=u.institution_id ${where.length?'WHERE '+where.join(' AND '):''} GROUP BY u.id,o.name,d.name,i.name ORDER BY u.username LIMIT $${values.length-1} OFFSET $${values.length}`,values); return {data:result.rows,page:query.page,pageSize:query.pageSize}; });
